// ============================================
// NS LUXURY VILLA — Message Outbox
// Mock email / WhatsApp messages generated by guest bookings and payments.
// Messages are stored in the database so they survive restarts and can be
// handed to a real provider adapter later without touching booking code.
// ============================================

import React, { useCallback, useEffect, useState } from 'react';
import { Inbox, Mail, MessageCircle, RefreshCw, Send, Eye } from 'lucide-react';
import {
  Badge,
  Button,
  DataTable,
  Modal,
  Pagination,
  SelectInput,
  showToast,
} from '../../components/ui';
import { outboxApi, type OutboxMessage } from '../../services/apiService';
import { useAuthStore } from '../../stores/authStore';

const statusVariant = (status: string): 'success' | 'warning' | 'danger' | 'neutral' => {
  if (status === 'SENT') return 'success';
  if (status === 'PENDING') return 'warning';
  if (status === 'FAILED') return 'danger';
  return 'neutral';
};

const channelVariant = (channel: string): 'info' | 'success' | 'neutral' => {
  if (channel === 'EMAIL') return 'info';
  if (channel === 'WHATSAPP') return 'success';
  return 'neutral';
};

const prettyDate = (value: string | null) =>
  value ? new Date(value).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : '—';

export const OutboxPage: React.FC = () => {
  const [items, setItems] = useState<OutboxMessage[]>([]);
  const [total, setTotal] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const [page, setPage] = useState(1);
  const [status, setStatus] = useState('');
  const [channel, setChannel] = useState('');
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState(false);
  const [selected, setSelected] = useState<OutboxMessage | null>(null);

  const canEdit = useAuthStore((s) => s.hasPermission('settings.edit'));
  const pageSize = 25;

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const result = await outboxApi.list({
        status: status || undefined,
        channel: channel || undefined,
        page,
        pageSize,
      });
      setItems(result.items || []);
      setTotal(result.total || 0);
      setTotalPages(result.totalPages || 1);
      setSelected((prev) => (prev ? result.items.find((m) => m.id === prev.id) || prev : prev));
    } catch (err) {
      showToast('error', err instanceof Error ? err.message : 'Unable to load the message outbox');
    } finally {
      setLoading(false);
    }
  }, [page, status, channel]);

  useEffect(() => {
    void load();
  }, [load]);

  const act = async (message: OutboxMessage, action: 'sent' | 'retry') => {
    try {
      setWorking(true);
      if (action === 'sent') {
        await outboxApi.markSent(message.id);
        showToast('success', 'Message marked as sent.');
      } else {
        await outboxApi.retry(message.id);
        showToast('success', 'Message returned to the pending queue.');
      }
      setSelected(null);
      await load();
    } catch (err) {
      showToast('error', err instanceof Error ? err.message : 'Unable to update the message');
    } finally {
      setWorking(false);
    }
  };

  const columns = [
    {
      key: 'channel',
      header: 'Channel',
      width: '110px',
      render: (m: OutboxMessage) => <Badge label={m.channel} variant={channelVariant(m.channel)} />,
    },
    {
      key: 'recipient',
      header: 'Recipient',
      render: (m: OutboxMessage) => (
        <div>
          <div className="font-semibold text-[var(--ns-ink)]">{m.recipient}</div>
          {m.subject && <div className="text-[12px] text-[var(--ns-muted)]">{m.subject}</div>}
        </div>
      ),
    },
    {
      key: 'template',
      header: 'Template',
      render: (m: OutboxMessage) => (
        <div>
          <div className="text-[12px] text-[var(--ns-ink)]">{m.template || '—'}</div>
          {m.relatedType && (
            <div className="text-[12px] text-[var(--ns-muted)]">
              {m.relatedType}
              {m.relatedId ? ` · ${m.relatedId.slice(0, 8)}…` : ''}
            </div>
          )}
        </div>
      ),
    },
    {
      key: 'status',
      header: 'Status',
      width: '110px',
      render: (m: OutboxMessage) => <Badge label={m.status} variant={statusVariant(m.status)} />,
    },
    {
      key: 'created',
      header: 'Queued',
      width: '170px',
      render: (m: OutboxMessage) => (
        <span className="text-[12px] text-[var(--ns-muted)]">{prettyDate(m.createdAt)}</span>
      ),
    },
    {
      key: 'actions',
      header: '',
      align: 'right' as const,
      render: (m: OutboxMessage) => (
        <button
          onClick={() => setSelected(m)}
          className="rounded-lg p-1.5 text-[var(--ns-muted)] ns-glass-hover hover:text-[var(--ns-gold)] bg-[var(--ns-glass-1)]"
          title="View message"
        >
          <Eye size={15} />
        </button>
      ),
    },
  ];

  return (
    <div className="workspace-page space-y-5 pb-16 animate-in fade-in duration-300">
      <header className="workspace-page__header">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-xl glass border border-[var(--ns-gold)]/40 text-[var(--ns-gold)]">
            <Inbox size={15} />
          </div>
          <div>
            <div className="workspace-page__eyebrow">Guest communication</div>
            <h1 className="workspace-page__title text-xl">Message Outbox</h1>
            <p className="workspace-page__subtitle text-[12px]">
              Mock email &amp; WhatsApp confirmations queued by website bookings and payments
            </p>
          </div>
        </div>
        <div className="workspace-page__actions">
          <Button
            variant="outline"
            size="sm"
            onClick={load}
            className="border-[var(--ns-glass-line)] glass ns-glass-hover text-[var(--ns-ink)] shadow-xs text-[12px] font-semibold gap-1.5"
          >
            <RefreshCw size={12} /> Refresh
          </Button>
        </div>
      </header>

      <div className="flex flex-col gap-3 rounded-2xl border border-[var(--ns-glass-line)] p-3 glass-subtle sm:flex-row sm:items-center sm:justify-between">
        <div className="flex flex-wrap items-center gap-2">
          <SelectInput
            value={channel}
            onChange={(e) => {
              setChannel(e.target.value);
              setPage(1);
            }}
            className="w-40"
          >
            <option value="">All channels</option>
            <option value="EMAIL">Email</option>
            <option value="WHATSAPP">WhatsApp</option>
          </SelectInput>
          <SelectInput
            value={status}
            onChange={(e) => {
              setStatus(e.target.value);
              setPage(1);
            }}
            className="w-40"
          >
            <option value="">All statuses</option>
            <option value="PENDING">Pending</option>
            <option value="SENT">Sent</option>
            <option value="FAILED">Failed</option>
          </SelectInput>
        </div>
        <span className="text-xs font-mono text-[var(--ns-muted)]">{total} message{total === 1 ? '' : 's'}</span>
      </div>

      <DataTable
        columns={columns}
        data={items}
        loading={loading}
        keyFn={(m) => m.id}
        onRowClick={(m) => setSelected(m)}
        emptyTitle="The outbox is empty"
        emptySubtitle="Confirmation emails and WhatsApp messages will appear here after a guest books or pays."
      />

      <Pagination page={page} totalPages={totalPages} total={total} onPageChange={setPage} />

      <Modal
        open={!!selected}
        onClose={() => setSelected(null)}
        title={selected ? `${selected.channel} message` : 'Message'}
        size="lg"
      >
        {selected && (
          <div className="space-y-4 text-xs">
            <div className="grid gap-3 sm:grid-cols-2">
              {[
                { label: 'Recipient', value: selected.recipient },
                { label: 'Channel', value: selected.channel },
                { label: 'Status', value: selected.status },
                { label: 'Template', value: selected.template || '—' },
                { label: 'Queued', value: prettyDate(selected.createdAt) },
                { label: 'Sent', value: prettyDate(selected.sentAt) },
                { label: 'Related', value: selected.relatedType ? `${selected.relatedType}${selected.relatedId ? ` · ${selected.relatedId}` : ''}` : '—' },
                { label: 'Attempts', value: String(selected.attempts) },
              ].map((row) => (
                <div key={row.label} className="rounded-xl border border-[var(--ns-glass-line)] glass-subtle p-2.5">
                  <div className="text-[12px] font-bold uppercase tracking-wider text-[var(--ns-muted)]">{row.label}</div>
                  <div className="mt-0.5 break-all font-semibold text-[var(--ns-ink)]">{row.value}</div>
                </div>
              ))}
            </div>

            {selected.subject && (
              <div>
                <div className="mb-1 text-[12px] font-bold uppercase tracking-wider text-[var(--ns-muted)]">Subject</div>
                <div className="rounded-xl border border-[var(--ns-glass-line)] glass-subtle p-3 font-semibold text-[var(--ns-ink)]">
                  {selected.subject}
                </div>
              </div>
            )}

            <div>
              <div className="mb-1 flex items-center gap-1.5 text-[12px] font-bold uppercase tracking-wider text-[var(--ns-muted)]">
                {selected.channel === 'EMAIL' ? <Mail size={12} /> : <MessageCircle size={12} />} Message body
              </div>
              <pre className="max-h-72 overflow-auto whitespace-pre-wrap rounded-xl border border-[var(--ns-glass-line)] glass-subtle p-3 font-sans text-xs leading-relaxed text-[var(--ns-ink)]">
                {selected.body}
              </pre>
            </div>

            {selected.lastError && (
              <div className="rounded-xl border border-[var(--ns-danger)] p-3 text-[var(--ns-danger)]">
                <div className="text-[12px] font-bold uppercase tracking-wider">Last error</div>
                <div className="mt-0.5">{selected.lastError}</div>
              </div>
            )}

            <div className="flex flex-wrap items-center justify-end gap-2 border-t border-[var(--ns-glass-line)] pt-3">
              <Button variant="outline" size="sm" onClick={() => setSelected(null)}>
                Close
              </Button>
              {canEdit && selected.status !== 'SENT' && (
                <Button
                  size="sm"
                  loading={working}
                  onClick={() => act(selected, 'sent')}
                  className="gap-1.5 font-bold"
                >
                  <Send size={13} /> Mark as sent
                </Button>
              )}
              {canEdit && selected.status === 'FAILED' && (
                <Button
                  variant="outline"
                  size="sm"
                  loading={working}
                  onClick={() => act(selected, 'retry')}
                  className="gap-1.5 font-bold"
                >
                  <RefreshCw size={13} /> Retry
                </Button>
              )}
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default OutboxPage;
